import {challenge as C} from './shared.js';
export default [
C(11,2,'实现可复查的输入噪声实验',{
 goal:'只对指定输入位置加噪，并保持目标不变。',signature:'noisy_inputs(inputs, targets, noise, mask, sigma)',contract:'四列表等长，sigma≥0。返回 (新输入列表,目标副本)。mask=True 的位置加 sigma*noise，其他输入保持原值。不得修改任何传入列表。',context:'“加入噪声”不是完整实验定义：加在哪里、什么分布、多大幅度、目标是否也变化，都影响训练任务。本题用给定噪声而非隐藏随机采样，确保能重现具体样本。',steps:['对每个位置检查 mask。','只改变输入，不对 targets 应用同样的噪声。','复制输出，方便和干净对照逐位置比较。'],worked:['inputs=[1,2]，noise=[1,-1]，mask=[True,False]。','sigma=0.5 时输入变为 [1.5,2]。','目标无论是什么都保持原值；这是带噪输入预测干净目标的实验约定。'],mistake:'同时扰动目标会变成另一种学习问题，不能与输入噪声实验混为一谈。',transfer:'真实噪声策略必须记录采样分布、seed 和位置；效果需通过独立长程指标验证。',cases:[['noisy_inputs([1,2],[3,4],[1,-1],[True,False],0.5)','([1.5,2],[3,4])','只扰动有效输入'],['noisy_inputs([1],[2],[9],[True],0)','([1],[2])','零噪声基线'],['noisy_inputs([0,0],[1,1],[-1,1],[True,True],2)','([-2,2],[1,1])','保留噪声方向']],solution:'def noisy_inputs(inputs,targets,noise,mask,sigma):\n    return [x+sigma*n if ok else x for x,n,ok in zip(inputs,noise,mask)],list(targets)\n',quiz:['对照 sigma=0 的意义是什么？',['保证最优','恢复干净输入基线','关闭模型参数'],1,'零噪声提供该变量的对照，而非对效果作出承诺。']
}),
C(11,4,'汇总多次实验而不只挑最好一次',{
 goal:'返回实验均值与样本标准差。',signature:'summarize_runs(values)',contract:'values 至少两个有限数。返回 {"mean":均值,"sample_std":使用 n-1 分母的标准差,"n":数量}。不删除表现差的运行。',context:'单个 seed 的优势可能只是波动。保留全部预先规划的运行，才能看出效果是否稳定。样本标准差描述这组运行的离散程度；它不是置信区间，也不自动给出统计显著性。',steps:['先算全部值的平均数。','累计每项与均值差的平方，除以 n-1。','开平方并返回 n，让读者知道证据规模。'],worked:['values=[1,3]，均值为 2。','平方偏差和为 2，n-1=1。','样本标准差为 sqrt(2)，不是 1。'],mistake:'只汇报最优 seed 会系统性夸大效果；分母 n 与 n-1 表示不同统计量。',transfer:'实验报告还应保存种子列表、失败运行和相同预算；均值加标准差不能替代失败分析。',cases:[['summarize_runs([1,3])','{"mean":2,"sample_std":1.4142135623730951,"n":2}','样本分母'],['summarize_runs([2,2,2])','{"mean":2,"sample_std":0,"n":3}','无波动'],['summarize_runs([-1,0,1])','{"mean":0,"sample_std":1,"n":3}','有正负结果']],solution:'import math\ndef summarize_runs(values):\n    n=len(values); mean=sum(values)/n\n    return {"mean":mean,"sample_std":math.sqrt(sum((v-mean)**2 for v in values)/(n-1)),"n":n}\n',quiz:['均值更好但标准差很大，最合适的结论是？',['已经证明稳定提升','需要检查运行分布并增加证据','忽略差的运行即可'],1,'波动影响结论稳定性，不能只保留最好一次。']
}),
C(11,6,'把长程失败按 horizon 展开',{
 goal:'在多条轨迹上按预测步聚合误差。',signature:'horizon_report(errors)',contract:'errors 为非空的非负误差列表的列表，每条轨迹长度可不同。返回各 horizon 的 (平均误差,样本数)；忽略没有该步的轨迹，不补零。所有轨迹均空时返回 []。',context:'一个总均值会掩盖远期崩坏，而变长轨迹会让远期样本数量下降。把每个 horizon 的均值和覆盖数量一起输出，能看出曲线变化是否伴随评测样本变化。',steps:['找出最大轨迹长度。','对每个 horizon 只收集实际存在该位置的误差。','返回均值和数量；缺失项不能当成零误差。'],worked:['errors=[[1,4],[3]]。','第一步有两个样本，均值 2；第二步只有一个，均值 4。','结果 [(2,2),(4,1)]，第二步不能除以轨迹总数 2。'],mistake:'用零补齐缺失的远期误差，会错误美化长程表现。',transfer:'不同模型比较时还需统一评测轨迹覆盖，避免一个模型提前终止而“少犯错误”。',cases:[['horizon_report([[1,4],[3]])','[(2,2),(4,1)]','变长覆盖'],['horizon_report([[],[2]])','[(2,1)]','空轨迹不补零'],['horizon_report([[],[]])','[]','无可评测位置']],solution:'def horizon_report(errors):\n    out=[]\n    for h in range(max(map(len,errors))):\n        values=[row[h] for row in errors if len(row)>h]\n        out.append((sum(values)/len(values),len(values)))\n    return out\n',quiz:['缺失的第 5 步误差能否补成 0？',['能','不能，缺失不代表完美预测','只有模型较大时能'],1,'需要报告覆盖数量，保持缺失与真实零误差的区别。']
}),
C(11,7,'周项目：生成配对消融实验结论',{
 goal:'按相同 seed 对比基线和变体，报告改善的均值与一致性。',signature:'paired_report(baseline, variant)',contract:'两个字典均为 seed→误差，seed 集合必须完全相同且非空，否则 ValueError。误差越低越好。返回 {"mean_improvement":平均 baseline-variant,"wins":严格改善的seed数,"n":总数}。',context:'配对比较让同一个 seed 下的两种配置对应起来，减少比较混乱。缺失运行必须显式处理，不能默默丢弃差的 seed。本题只汇总给定结果，不宣称通过均值和胜率就得到了因果证明。',steps:['先比较键集合，拒绝不完整配对。','每个 seed 计算 baseline-variant，正数表示误差降低。','统计均值、正数数量和总数，不把持平算作胜利。'],worked:['baseline={1:2,2:4}，variant={1:1,2:5}。','改善分别为 1、-1，均值 0，wins=1。','不能只展示 seed=1 并声称稳定提升。'],mistake:'把两个字典的 values 直接 zip，可能配错 seed。',transfer:'正式报告仍需核对数据、预算、初始化和评测协议一致，并保留失败样例及下一轮可否定假设。',cases:[['paired_report({1:2,2:4},{2:5,1:1})','{"mean_improvement":0,"wins":1,"n":2}','按键而非顺序配对'],['paired_report({1:2,2:3},{1:1,2:2})','{"mean_improvement":1,"wins":2,"n":2}','一致改善'],['paired_report({1:2},{1:2})','{"mean_improvement":0,"wins":0,"n":1}','持平不是获胜']],extraTests:[{name:'拒绝缺失 seed',code:'try:\n    paired_report({1:2,2:3},{1:1})\n    assert False\nexcept ValueError: pass'}],solution:'def paired_report(baseline,variant):\n    if not baseline or baseline.keys()!=variant.keys(): raise ValueError("unpaired seeds")\n    differences=[baseline[k]-variant[k] for k in baseline]\n    return {"mean_improvement":sum(differences)/len(differences),"wins":sum(d>0 for d in differences),"n":len(differences)}\n',quiz:['两个 seed 分别改善 1 和退化 1，能称为稳定提升吗？',['能，至少一个变好','不能，平均为零且方向不一致','删除退化 seed 后就能'],1,'完整结果没有提供稳定改善的证据。']
})];
